const listaAsistencia = $memory.getJson("ListaAsistencia", {});

const asist_curso_id = listaAsistencia[0].id_asistencia;
const asist_curso_cedula = listaAsistencia[0].identificacion;
const asist_curso_servicio = listaAsistencia[0].nombre_servicio;
const asist_curso_expediente = listaAsistencia[0].id_expediente;

$memory.set("id_asistencia", asist_curso_id, 86400);
$memory.set("cveafiliado", asist_curso_cedula, 86400);
$memory.set("service", asist_curso_servicio, 86400);
$memory.set("id_expediente", asist_curso_expediente, 86400);

let asistenciasActuales = $memory.getJson("asistenciaCurso", {})|| null;
let tamanio =  asistenciasActuales ? asistenciasActuales.length : 0;

if (tamanio > 1){
    asistenciasActuales = asistenciasActuales.slice(0, 9);//toma los 10 ultimo
}

asistenciasActuales = asistenciasActuales.map((item, index) =>({
    ...item,
    numero: index + 1,
    texto_opcion: `Asistencia No ${item.id_asistencia}`
}))

$memory.setJson('ListaAsistencia', asistenciasActuales, 86400);
$memory.set('tamanio', tamanio);

